struct Node;

/// Truncate a string to at most `max` bytes without splitting a UTF-8
/// character, so the `len(question) <= 512` postcondition holds even if an
/// input somehow arrived longer than the precondition promised.
fn clamp(mut s: String, max: usize) -> String {
    if s.len() > max {
        let mut end = max;
        while end > 0 && !s.is_char_boundary(end) {
            end -= 1;
        }
        s.truncate(end);
    }
    s
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let cq = query.query;

        // Approved enrichment call. Its result does not change the output;
        // the node fetches it for the metadata side-effect only.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            cq.question
        );
        let _ = crate::aap::caps::http_client::get(&url);

        // Read-only knowledge-base lookup is the node's substantive work.
        let mut knowledge = crate::aap::caps::kb_read::lookup(&cq.question);

        // ensures present(knowledge): guarantee a non-empty list.
        if knowledge.is_empty() {
            knowledge.push(String::new());
        }

        // ensures len(question) <= 512.
        let question = clamp(cq.question, 512);

        ConversationContext {
            intent: cq.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
